/bin/bash -lc "python3 -B - <<'PY'
import unittest
from scripts.tests import test_completion_gate as tests

class MemoryPath:
    def __init__(self, files, name=''):
        self.files, self.name = files, name
    def __truediv__(self, rel):
        return MemoryPath(self.files, self.name + '/' + str(rel))
    @property
    def parent(self):
        return self
    def mkdir(self, **kwargs):
        pass
    def is_file(self):
        return self.name in self.files
    def read_text(self, **kwargs):
        return self.files[self.name]
    def write_text(self, text, **kwargs):
        self.files[self.name] = text
    def unlink(self):
        del self.files[self.name]

class InMemoryBoundLedgerTests(tests.BoundLedgerTests):
    def setUp(self):
        self.root = MemoryPath({})
        self.track = tests.track_for(self.root)
        tests.write(self.root, self.LEDGER, tests.GOOD_LEDGER)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(InMemoryBoundLedgerTests)
result = unittest.TextTestRunner(verbosity=1).run(suite)
raise SystemExit(not result.wasSuccessful())
PY"

